import{z as n,x as s,o as l,c as d,q as t,j as A,D as e,d as B,s as i,S as o,b as a}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"多文档负载","description":"","frontmatter":{"title":"多文档负载","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/lc-multidoc-workload.md","filePath":"llm/lc-multidoc-workload.md","lastUpdated":1791063341000}'),m={name:"llm/lc-multidoc-workload.md"};function p(h,E,c,C,u,f){const r=s("Mermaid");return l(),d("div",null,[E[2]||(E[2]=t('<h1 id="多文档负载" tabindex="-1">多文档负载 <a class="header-anchor" href="#多文档负载" aria-label="Permalink to &quot;多文档负载&quot;">​</a></h1><div class="epigraph"><p>多文档负载的显存账不由文档数决定，由共享结构决定；前缀树划在哪，账就从三个数量级掉到一个。</p><footer>—— 据 Juravsky et al., Hydragen, 2024 与 Zheng et al., SGLang / RadixAttention, NeurIPS 2024 整理</footer></div><p><a href="/llm/lc-longoutput-streaming">上一课</a>立起长输出的流式语义。本课处理一类把前几课杠杆同时用满的负载：多文档。一库多问——同一合同库被上千人问上千次；一问多档——把二十份标书推进一个窗口交叉比对。形态不同，共享点相同：上下文里有一大段公共前缀。<a href="/llm/kv-prefix-cache">前缀共享的键语义</a>与<a href="/llm/lc-context-cache-tiers">缓存分层</a>已立；本课讲共享结构本身怎么组织、怎么失效、怎么批量兑现。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无共享时多文档负载在算术上就不可行：100 个请求各带 100K 的同一语料，是约 1.28 TB 的 KV——没有池子接得住，而其中九成九是同一份数据的副本。组织成共享前缀后，账变成「一份语料加每问一小段后缀」，差出几十倍。但共享不是免费的，三个坑紧跟着来。其一在树的组织：划粗了，一条文档更新作废整棵子树；划细了，命中碎、元数据涨。其二在窗口内：一问多档把多文档拼进一个上下文，排列与干扰开始影响质量（<a href="/llm/context-rot">context rot</a>）——拼序是质量参数，不是格式细节。其三在权限：共享前缀的命中若不带租户边界，A 部门的缓存会喂给 B 部门。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三件事。库组织：语料按「系统段加稳定文档段」建树，版本进键（<a href="/llm/lc-context-cache-tiers">分层课</a>的版本化）；失效按文档段落级传播，半径对齐到真正变了的前缀——变更频率分层放置，稳定的系统提示放深处，易变的附录放浅处。批处理杠杆：同库并发请求的共享前缀读取用 <a href="/llm/hydragen">Hydragen</a> 一类分解——前缀 KV 一次读入、跨序列批量查询、log-sum-exp 精确合并，加速随 batch 与前缀长度涨；没有共享结构的负载吃不到这个杠杆，不要硬套。放置与权限：<a href="/llm/sglang-router">亲和路由</a>把同库流量钉进同副本，命中键带租户与库版本；一问多档的拼序由<a href="/llm/lc-retrieval-hybrid-serving">组装层</a>显式受控，文档边界元数据随上下文传给生成端，引用才能回指到份。</p>',7)),(l(),A(o,null,{default:e(()=>[i(r,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20ROOT%5B%22%E6%A0%91%E6%A0%B9%EF%BC%9A%E7%B3%BB%E7%BB%9F%E6%AE%B5%EF%BC%88%E6%9C%80%E7%A8%B3%E5%AE%9A%EF%BC%89%22%5D%20--%3E%20LIB%5B%22%E5%BA%93%E6%AE%B5%EF%BC%9A%E6%96%87%E6%A1%A3%E6%8C%89%E5%8F%98%E6%9B%B4%E9%A2%91%E7%8E%87%E5%88%86%E5%B1%82%22%5D%0A%20%20LIB%20--%3E%20DA%5B%22%E7%A8%B3%E5%AE%9A%E6%96%87%E6%A1%A3%E6%AE%B5%EF%BC%9A%E6%94%BE%E6%B7%B1%E5%A4%84%22%5D%0A%20%20LIB%20--%3E%20DB%5B%22%E6%98%93%E5%8F%98%E9%99%84%E5%BD%95%E6%AE%B5%EF%BC%9A%E6%94%BE%E6%B5%85%E5%A4%84%22%5D%0A%20%20DA%20--%3E%20Q1%5B%22%E8%AF%B7%E6%B1%82%20A%EF%BC%9A%E7%8B%AC%E6%9C%89%E5%90%8E%E7%BC%80%22%5D%0A%20%20DB%20--%3E%20Q2%5B%22%E8%AF%B7%E6%B1%82%20B%EF%BC%9A%E7%8B%AC%E6%9C%89%E5%90%8E%E7%BC%80%22%5D%0A%20%20Q1%20-.-%3E%7C%22%E6%96%87%E6%A1%A3%E6%9B%B4%E6%96%B0%E5%8F%AA%E4%BD%9C%E5%BA%9F%E6%89%80%E5%9C%A8%E5%88%86%E6%94%AF%22%7C%20INV%5B%22%E5%A4%B1%E6%95%88%E5%8D%8A%E5%BE%84%20%3D%20%E6%89%80%E5%9C%A8%E5%AD%90%E6%A0%91%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[B("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"共享前缀是多文档唯一的一阶杠杆，理由在 KV 的确定性：KV 是前缀的确定函数，同前缀同 KV，复制它纯属浪费——树、批处理、亲和路由都在兑现这一条。失效半径与命中长度的牵制是库组织的中心权衡，分段粒度是这条权衡唯一的定价旋钮；「按变更频率分层」比统一粒度好，因为它让最常变的段持有最短的半径，作废成本被压到最低。一问多档窗口内的质量衰减，服务侧能控制的是排列（关键档放两端）与边界元数据，控制不了衰减本身——这句边界要写进语义。",-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"算一遍共享的账：每 token 128 KiB（8B FP16）下，100 请求各带 100K 语料是 1.28 TB；共享后语料付一次 12.8 GiB，每问 2K 后缀各付 256 MiB，合计约 38 GiB——差出 34 倍，全部来自「副本变共享」这一个动作。")],-1)),E[6]||(E[6]=a("p",null,"共享的批处理杠杆（Hydragen 式分解）是怎么把「读一次」兑现成加速的，单独画出来。",-1)),(l(),A(o,null,{default:e(()=>[i(r,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E5%90%8C%E5%BA%93%20100%20%E4%B8%AA%E5%B9%B6%E5%8F%91%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20SPLIT%5B%22%E6%8C%89%E5%89%8D%E7%BC%80%E5%88%86%E8%A7%A3%EF%BC%9A%E5%85%B1%E4%BA%AB%E6%AE%B5%20%2B%20%E7%8B%AC%E6%9C%89%E5%90%8E%E7%BC%80%22%5D%0A%20%20SPLIT%20--%3E%20ONCE%5B%22%E5%85%B1%E4%BA%AB%E5%89%8D%E7%BC%80%20KV%20%E5%8F%AA%E8%AF%BB%E5%85%A5%E4%B8%80%E6%AC%A1%22%5D%0A%20%20ONCE%20--%3E%20ATT%5B%22%E5%90%84%E5%BA%8F%E5%88%97%E5%9C%A8%E5%85%B1%E4%BA%AB%20KV%20%E4%B8%8A%E6%89%B9%E9%87%8F%E6%9F%A5%E8%AF%A2%22%5D%0A%20%20ATT%20--%3E%20MERGE%5B%22log-sum-exp%20%E7%B2%BE%E7%A1%AE%E5%90%88%E5%B9%B6%E5%90%84%E6%AE%B5%E6%B3%A8%E6%84%8F%E5%8A%9B%22%5D%0A%20%20MERGE%20--%3E%20OUT%5B%22%E5%90%84%E8%87%AA%E8%BE%93%E5%87%BA%EF%BC%8C%E4%BA%92%E4%B8%8D%E5%8F%AF%E8%A7%81%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p><span class="marginnote">直觉类比：共享前缀像合租公寓的公共家具——客厅的沙发买一套就够，卧室的东西才单买。前缀树就是把「哪些公共、哪些私有」画成家谱：越靠根越公共，越靠叶越私有；一张沙发换新（文档更新），只需通知住那个房间的人，这就是失效半径对齐子树。</span></p><p><span class="marginnote">常见误区：容易把缓存命中当纯性能问题，忘了命中键里要带租户与库版本。少了这一位，A 部门的私有合同缓存会原样喂给 B 部门的请求——一次性能优化瞬间变成数据泄漏事故。</span></p><p>不写检索选档（<a href="/llm/lc-retrieval-hybrid-serving">混合服务课</a>已立），不写窗口内衰减的机理（<a href="/llm/context-rot">context rot 课</a>已立）。跨租户共享公共语料（同一份公开手册）与租户内共享是两种键策略：前者要防跨租户的计时侧信道——共享是性能语义，不是安全语义，安全边界仍由键隔离兜底。库很大而问题稀疏时，整库进树不如按需圈定：树的组织成本要由命中率偿还，稀疏负载下<a href="/llm/lc-retrieval-hybrid-serving">检索圈定</a>更便宜。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>多文档负载的一阶杠杆是共享前缀：无共享 1.28 TB，共享后 38 GiB，账由共享结构决定。</li><li>库组织按变更频率分层：稳定段放深处，易变段放浅处，失效半径对齐到子树。</li><li>同库并发的批处理用共享前缀分解（Hydragen 式），无共享结构的负载不硬套。</li><li>一问多档的拼序与文档边界元数据是质量与引用的前提，由组装层受控。</li><li>权限与租户边界进缓存键；共享是性能语义，安全仍靠键隔离。</li><li>出处：Juravsky et al., Hydragen（arXiv:2402.05099）；Zheng et al., NeurIPS 2024；键与失效口径同本仓库前缀缓存诸课。</li></ul>',6))])}const g=n(m,[["render",p]]);export{F as __pageData,g as default};
